import mongoose from 'mongoose';
import { toJSONPlugin } from './plugins.js';

export const CONSENT_DECISIONS = ['accepted', 'rejected', 'custom'];

// Cookie consent record from the website banner, one per visitor (browser).
// Email/name are optional: collected only when the visitor chooses to share them.
const cookieConsentSchema = new mongoose.Schema(
  {
    // Random id generated by the website and stored in the visitor's cookie
    visitorId: { type: String, required: true, unique: true, trim: true, maxlength: 64 },
    decision: { type: String, enum: CONSENT_DECISIONS, required: true },
    preferences: {
      necessary: { type: Boolean, default: true },
      functional: { type: Boolean, default: false },
      analytics: { type: Boolean, default: false },
      marketing: { type: Boolean, default: false },
    },
    email: {
      type: String,
      lowercase: true,
      trim: true,
      maxlength: 254,
      match: [/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/, 'Enter a valid email address'],
    },
    name: { type: String, trim: true, maxlength: 100 },
    phone: { type: String, trim: true, maxlength: 20 },
    company: { type: String, trim: true, maxlength: 120 },
    marketingOptIn: { type: Boolean, default: false },
    policyVersion: { type: String, trim: true, maxlength: 20, default: '1.0' },
    // Context captured at consent time (proof of consent)
    page: { type: String, trim: true, maxlength: 500 },
    referrer: { type: String, trim: true, maxlength: 500 },
    language: { type: String, trim: true, maxlength: 20 },
    timezone: { type: String, trim: true, maxlength: 60 },
    screen: { type: String, trim: true, maxlength: 20 },
    userAgent: { type: String, trim: true, maxlength: 500 },
    ip: { type: String, select: false },
    user: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
    consentedAt: { type: Date, default: Date.now },
    withdrawnAt: Date,
  },
  { timestamps: true }
);

cookieConsentSchema.index({ decision: 1, createdAt: -1 });
cookieConsentSchema.index({ email: 1 }, { sparse: true });

cookieConsentSchema.plugin(toJSONPlugin);

export default mongoose.model('CookieConsent', cookieConsentSchema);
